\begin{theorem}[PFR]\label{pfr-torsion}  Suppose that $G$ is an abelian group of torsion $m$ (not necessarily finite).
  If $A \subset G$ is a finite non-empty set with $|A+A| \leq K|A|$, then $A$ can be covered by at most $mK^{256m^3+1}$ translates of a finite subspace $H$ of $G$ with $|H| \leq |A|$.
  \end{theorem}
